// Compute the Weyl sum  S(alpha; N, k) = sum_{n=1..N} e(2*pi*i*alpha*n^k)
// and report its magnitude / N (the Weyl-criterion ratio).
// Try:
//   alpha = sqrt(2)        // irrational, ratio -> 0 as N grows
//   alpha = 1/3            // rational, ratio stays away from 0 when k=1
//   alpha = 0.5*Math.sqrt(5) - 0.5  // golden ratio - 1 (badly approximable)
//   k = 1, 2, 3, 4         // higher k gets harder per Weyl's inequality
const alpha = Math.sqrt(2);
const k = 2;
const Ns = [100, 1000, 10000, 50000];
for (const N of Ns) {
  let re = 0, im = 0;
  for (let n = 1; n <= N; n++) {
    const theta = 2 * Math.PI * alpha * Math.pow(n, k);
    re += Math.cos(theta);
    im += Math.sin(theta);
  }
  const mag = Math.sqrt(re*re + im*im);
  console.log('N = ' + N + ':  |S| = ' + mag.toFixed(2)
    + ',   |S|/N = ' + (mag/N).toFixed(4)
    + ',   |S|/sqrt(N) = ' + (mag/Math.sqrt(N)).toFixed(3));
}
// Weyl's criterion: |S|/N -> 0 means {alpha n^k} is equidistributed.
// Square-root heuristic: |S| ~ sqrt(N) for generic irrational alpha.

