const svg = $('#ls-svg'), out = $('#ls-out');
const QR = $('#ls-Q'), Qv = $('#ls-Qv');
const NR = $('#ls-N'), Nv = $('#ls-Nv');
const W = 620, H = 320, pad = 50;
function gcd(a,b){ while(b){[a,b]=[b,a%b];} return a; }
// simulate large-sieve LHS for the test sequence a_n = 1 for n<=N, else 0
// -- against Farey rationals a/q with q in [1..Qmax]: |sum_{n<=N} e(n*a/q)|^2
// -- Plancherel form (frequencies are Q^{-2}-spaced via Farey)
function lsSimulated(Qmax, N){
  let total = 0;
  let count = 0;
  for(let q=1; q<=Qmax; q++){
    for(let a=1; a<=q; a++){
      if(gcd(a,q) !== 1) continue;
      const alpha = a/q;
      // |sum_{n<=N} e(n alpha)|^2 = |(e((N+1)alpha) - e(alpha))/(e(alpha)-1)|^2
      // for alpha != 0, otherwise N^2.
      if(Math.abs(alpha - Math.round(alpha)) < 1e-12){
        total += N*N;
      } else {
        const num = Math.sin(Math.PI * alpha * N) / Math.sin(Math.PI * alpha);
        total += num * num;
      }
      count++;
    }
  }
  return {total, count};
}
function draw(){
  svg.innerHTML = '';
  const Qmax = parseInt(QR.value, 10);
  const N = parseInt(NR.value, 10);
  Qv.textContent = 'Q = ' + Qmax;
  Nv.textContent = 'N = ' + N;

  // sample LHS over Q = 2..Qmax
  const Qs = [], lhs = [], rhs = [];
  for(let Q=2; Q<=Qmax; Q++){
    const {total} = lsSimulated(Q, N);
    Qs.push(Q);
    lhs.push(total);
    // RHS is (Q^2 + N) * ||a||^2 = (Q^2 + N) * N
    rhs.push((Q*Q + N) * N);
  }
  const allVals = lhs.concat(rhs);
  const ymax = Math.max(...allVals) * 1.1 + 1;
  const xmin = 2, xmax = Qmax;
  const toX = q => pad + (q-xmin)/(xmax-xmin)*(W-2*pad);
  const toY = y => H - pad - y/ymax*(H-2*pad);

  // axes
  svg.appendChild(SVG('line',{x1:pad, y1:toY(0), x2:W-pad, y2:toY(0), stroke:'var(--mute)'}));
  svg.appendChild(SVG('line',{x1:pad, y1:toY(0), x2:pad, y2:toY(ymax), stroke:'var(--mute)'}));

  // RHS = (Q^2+N) N curve (cyan dashed)
  let dR = '';
  for(let i=0; i<Qs.length; i++){
    dR += (i===0?'M':'L') + toX(Qs[i]) + ' ' + toY(rhs[i]) + ' ';
  }
  svg.appendChild(SVG('path',{d:dR, fill:'none', stroke:'var(--cyan)', 'stroke-width':2, 'stroke-dasharray':'5 4'}));

  // LHS curve (yellow solid)
  let dL = '';
  for(let i=0; i<Qs.length; i++){
    dL += (i===0?'M':'L') + toX(Qs[i]) + ' ' + toY(lhs[i]) + ' ';
  }
  svg.appendChild(SVG('path',{d:dL, fill:'none', stroke:'var(--yellow)', 'stroke-width':2}));

  // x ticks
  for(let k=0; k<=5; k++){
    const v = Math.round(xmin + (xmax-xmin)*k/5);
    const t = SVG('text',{x:toX(v), y:toY(0)+18, 'text-anchor':'middle','font-size':11, fill:'var(--mute)'});
    t.textContent = v; svg.appendChild(t);
  }
  const xlab = SVG('text',{x:W/2, y:H-8, 'text-anchor':'middle','font-size':11, fill:'var(--mute)'});
  xlab.textContent = 'modulus cutoff Q'; svg.appendChild(xlab);

  // legend (viewport coords)
  const items = [
    ['— Σ_{q≤Q} Σ_χ* |Σ a_n χ(n)|² (LHS, simulated)', 'var(--yellow)'],
    ['- - (Q² + N)·||a||² (large-sieve bound)', 'var(--cyan)']
  ];
  items.forEach((it, i) => {
    const t = SVG('text',{x:pad+10, y:pad+14+i*16, 'font-size':12, fill:it[1]});
    t.textContent = it[0]; svg.appendChild(t);
  });

  const lhsAtQ = lhs[lhs.length-1];
  const rhsAtQ = rhs[rhs.length-1];
  const slack = rhsAtQ / Math.max(1, lhsAtQ);
  out.textContent = 'Q = ' + Qmax + ', N = ' + N + ':  LHS ≈ ' + lhsAtQ.toFixed(0)
    + ',   (Q²+N)·N = ' + rhsAtQ.toFixed(0)
    + ',   slack = RHS/LHS ≈ ' + slack.toFixed(2)
    + '\nLarge sieve is sharp up to a constant; here the test sequence (a_n = 1) is concentrated, so the bound is essentially tight.';
}
QR.addEventListener('input', draw);
NR.addEventListener('input', draw);
draw();
